import { MapleSpendingDonut, useQuery } from "@vendo/screen";

export default function MoneyHq() {
  const accounts = useQuery("host_listAccounts").data;
  const slices = useQuery("host_getSpendingInsights").data;
  const goals = useQuery("host_listGoals").data;
  const bills = useQuery("host_listScheduledPayments").data;

  const ink = "#111111";
  const muted = "#908C85";
  const faint = "#C0BDB8";
  const line = "#E8E9EE";
  const rail = "#F0F1F5";
  const card = "#FFFFFF";
  const page = "#F5F6FA";
  const danger = "#EF4444";
  const shadow = "0 1px 4px rgba(0,0,0,0.04)";

  // Maple money is integer CENTS. Hand-rolled rather than toLocaleString:
  // the screen runs in QuickJS, which carries no Intl, so the locale
  // arguments are silently ignored there and $2,850.00 renders as 2850.
  const money = (cents) => {
    const negative = cents < 0;
    const value = negative ? -cents : cents;
    const frac = value % 100;
    let rest = (value - frac) / 100;
    let grouped = "";
    while (rest >= 1000) {
      const chunk = rest % 1000;
      rest = (rest - chunk) / 1000;
      grouped = "," + (chunk < 10 ? "00" + chunk : chunk < 100 ? "0" + chunk : "" + chunk) + grouped;
    }
    return (negative ? "-$" : "$") + rest + grouped + "." + (frac < 10 ? "0" + frac : "" + frac);
  };

  const capitalize = (word) => word.charAt(0).toUpperCase() + word.slice(1);

  const monthName = (month) => month === "01" ? "Jan"
    : month === "02" ? "Feb" : month === "03" ? "Mar" : month === "04" ? "Apr"
    : month === "05" ? "May" : month === "06" ? "Jun" : month === "07" ? "Jul"
    : month === "08" ? "Aug" : month === "09" ? "Sep" : month === "10" ? "Oct"
    : month === "11" ? "Nov" : "Dec";

  // Same reason as money(): toLocaleDateString has no Intl to read here.
  const prettyDate = (iso) => {
    const day = iso.slice(8, 10);
    return monthName(iso.slice(5, 7)) + " " + (day.charAt(0) === "0" ? day.slice(1) : day) + ", " + iso.slice(0, 4);
  };

  const daysUntil = (iso) => Math.round((new Date(iso).getTime() - Date.now()) / 86400000);

  const categoryColor = (category) => category === "housing" ? "#6366F1"
    : category === "shopping" ? "#F59E0B" : category === "transport" ? "#3B82F6"
    : category === "subscriptions" ? "#8B5CF6" : category === "dining" ? "#EC4899"
    : category === "groceries" ? "#1DB87A" : category === "coffee" ? "#92400E"
    : category === "income" ? "#0EA5E9" : category === "transfer" ? "#64748B" : "#A1A1AA";

  const goalColor = (index) => index % 5 === 0 ? "#3B82F6"
    : index % 5 === 1 ? "#1DB87A" : index % 5 === 2 ? "#8B5CF6"
    : index % 5 === 3 ? "#F59E0B" : "#EC4899";

  const smallCaps = {
    fontSize: 11,
    fontWeight: 700,
    letterSpacing: "0.1em",
    textTransform: "uppercase",
    color: muted,
  };
  const panel = {
    backgroundColor: card,
    border: "1px solid " + line,
    borderRadius: 14,
    boxShadow: shadow,
  };
  const emptyLine = { fontSize: 13, color: muted, padding: "14px 2px" };

  const netWorth = accounts.reduce((total, account) => total + account.balance, 0);
  const ranked = slices.slice().sort((left, right) => right.amount - left.amount);
  const spent = ranked.reduce((total, slice) => total + slice.amount, 0);

  return (
    <div style={{ backgroundColor: page, fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif", paddingBottom: 40 }}>
      <div style={{ backgroundColor: card, borderBottom: "1px solid " + line, padding: "28px 24px 20px", maxWidth: 680, margin: "0 auto" }}>
        <div style={{ fontSize: 26, fontWeight: 700, color: ink, letterSpacing: "-0.5px" }}>Money HQ</div>
        <div style={{ fontSize: 14, color: muted, marginTop: 2 }}>Your financial snapshot</div>
      </div>

      <div style={{ maxWidth: 680, margin: "0 auto", padding: "0 16px" }}>
        <div style={{ marginTop: 28, marginBottom: 14, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={smallCaps}>Account Balances</div>
          <div style={{ backgroundColor: ink, color: "#FFFFFF", borderRadius: 20, padding: "4px 14px", fontSize: 13, fontWeight: 600, letterSpacing: "-0.2px" }}>
            Net {money(netWorth)}
          </div>
        </div>
        {accounts.length === 0 && <div style={emptyLine}>No accounts to show.</div>}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 12 }}>
          {accounts.map((account) => {
            const credit = account.kind === "credit";
            const accent = account.kind === "checking" ? "#1DB87A"
              : account.kind === "savings" ? "#3B82F6"
              : credit ? danger : "#8B5CF6";
            const kind = account.kind === "checking" ? "Checking"
              : account.kind === "savings" ? "Savings"
              : credit ? "Credit" : "Investing";
            const points = account.sparkline;
            const low = points.reduce((least, point) => point < least ? point : least, points[0]);
            const high = points.reduce((most, point) => point > most ? point : most, points[0]);
            const spread = high - low === 0 ? 1 : high - low;
            return (
              <div style={{ ...panel, padding: "18px 18px 14px", display: "flex", flexDirection: "column", gap: 10 }}>
                <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 8 }}>
                  <div>
                    <div style={{ fontSize: 14, fontWeight: 600, color: ink }}>{account.name}</div>
                    <div style={{ fontSize: 12, color: muted, marginTop: 1 }}>••{account.mask}</div>
                  </div>
                  <div style={{ backgroundColor: accent + "18", color: accent, borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 600, whiteSpace: "nowrap" }}>
                    {kind}
                  </div>
                </div>
                <div style={{ fontSize: 22, fontWeight: 700, color: credit ? danger : ink, letterSpacing: "-0.5px" }}>
                  {credit ? money(account.balance < 0 ? -account.balance : account.balance) + " owed" : money(account.balance)}
                </div>
                {points.length > 1 && (
                  <div style={{ display: "flex", alignItems: "flex-end", gap: 2, height: 34 }}>
                    {points.map((point) => (
                      <div style={{
                        width: 4,
                        backgroundColor: accent,
                        opacity: 0.5,
                        borderRadius: 2,
                        // Pixels, never a percentage: the renderer wraps every node
                        // in its own box, so a percentage height would resolve
                        // against that wrapper's auto height and collapse.
                        height: 5 + Math.round(((credit ? high - point : point - low) / spread) * 29),
                      }} />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div style={{ marginTop: 32, marginBottom: 14 }}>
          <div style={smallCaps}>Spending by Category</div>
        </div>
        <div style={{ ...panel, padding: "24px 20px" }}>
          {ranked.length === 0 && <div style={emptyLine}>No spending this period.</div>}
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
            <div style={{ display: "flex", justifyContent: "center" }}>
              <MapleSpendingDonut slices={ranked} size={180} />
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px 16px" }}>
              {ranked.map((slice) => (
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
                    <div style={{ width: 10, height: 10, borderRadius: 3, backgroundColor: categoryColor(slice.category) }} />
                    <div style={{ fontSize: 12, color: ink, fontWeight: 500, whiteSpace: "nowrap" }}>
                      {capitalize(slice.category)}
                    </div>
                  </div>
                  <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                    <div style={{ fontSize: 12, color: muted, whiteSpace: "nowrap" }}>{money(slice.amount)}</div>
                    <div style={{ fontSize: 11, color: faint, whiteSpace: "nowrap" }}>
                      {spent === 0 ? 0 : Math.round((slice.amount / spent) * 100)}%
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div style={{ marginTop: 32, marginBottom: 14 }}>
          <div style={smallCaps}>Savings Goals</div>
        </div>
        {goals.length === 0 && <div style={emptyLine}>No savings goals yet.</div>}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12 }}>
          {goals.map((goal, index) => {
            const accent = goalColor(index);
            const ratio = goal.target === 0 ? 0 : goal.saved / goal.target;
            const status = ratio >= 0.7 ? "Almost there!" : ratio >= 0.4 ? "On track" : "Keep going";
            const statusColor = ratio >= 0.7 ? "#1DB87A" : ratio >= 0.4 ? "#3B82F6" : "#F59E0B";
            return (
              <div style={{ ...panel, padding: "18px 16px", display: "flex", flexDirection: "column", gap: 12 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <div style={{ width: 12, height: 12, borderRadius: 4, backgroundColor: accent }} />
                  <div>
                    <div style={{ fontSize: 14, fontWeight: 600, color: ink }}>{goal.name}</div>
                    <div style={{ fontSize: 11, color: statusColor, fontWeight: 600, marginTop: 1 }}>{status}</div>
                  </div>
                </div>
                <div style={{ backgroundColor: rail, borderRadius: 99, height: 7, overflow: "hidden" }}>
                  {/* A pixel height, not "100%": the fill sits inside the renderer's
                      own auto-height wrapper, which a percentage cannot resolve against. */}
                  <div style={{ height: 7, width: (ratio > 1 ? 100 : ratio * 100) + "%", backgroundColor: accent, borderRadius: 99 }} />
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: ink }}>{money(goal.saved)}</div>
                  <div style={{ fontSize: 12, color: muted }}>of {money(goal.target)}</div>
                </div>
                <div style={{ fontSize: 12, color: accent, fontWeight: 600 }}>{(ratio * 100).toFixed(1)}% complete</div>
              </div>
            );
          })}
        </div>

        <div style={{ marginTop: 32, marginBottom: 14 }}>
          <div style={smallCaps}>Upcoming Bills</div>
        </div>
        <div style={{ ...panel, overflow: "hidden" }}>
          {bills.length === 0 && <div style={{ ...emptyLine, padding: "16px 18px" }}>Nothing scheduled.</div>}
          {bills.map((bill, index) => {
            const days = daysUntil(bill.nextDate);
            const soon = days <= 7;
            return (
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "16px 18px", borderBottom: index < bills.length - 1 ? "1px solid " + rail : "none" }}>
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 14, fontWeight: 600, color: ink }}>{bill.payeeName}</div>
                  <div style={{ fontSize: 12, color: muted, marginTop: 2 }}>{capitalize(bill.cadence)}</div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontSize: 15, fontWeight: 700, color: ink }}>{money(bill.amount < 0 ? -bill.amount : bill.amount)}</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 3, justifyContent: "flex-end" }}>
                    <div style={{ fontSize: 12, color: muted }}>{prettyDate(bill.nextDate)}</div>
                    <div style={{ backgroundColor: soon ? "#FEF3C7" : rail, color: soon ? "#D97706" : muted, borderRadius: 20, padding: "2px 8px", fontSize: 11, fontWeight: 600, whiteSpace: "nowrap" }}>
                      {days <= 0 ? "Today" : days === 1 ? "Tomorrow" : days + "d"}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
